#include <bits/stdc++.h>
using namespace std;

vector<string> findRelativeRanks(vector<int>& score) {
    int n = score.size();
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) { return score[a] > score[b]; });  // sort indices, once

    vector<string> result(n);
    vector<string> medals = {"Gold Medal", "Silver Medal", "Bronze Medal"};
    for (int rank = 0; rank < n; rank++) {
        int i = order[rank];
        result[i] = rank < 3 ? medals[rank] : to_string(rank + 1);
    }
    return result;
}
